// Получаем ответ от AI Agent
const aiResponse = $input.first().json.output;

// Проверяем, содержит ли ответ формат tavily(query="...")
const tavilyPattern = /tavily\(query="([^"]+)"\)/;
const match = aiResponse.match(tavilyPattern);

if (match) {
  // Найден запрос для Tavily
  return {
    json: {
      needsTavily: true,
      tavilyQuery: match[1],
      originalMessage: aiResponse,
      chatId: $('Load Static Data').first().json.chatId,
      messageText: $('Load Static Data'). first().json.messageText
    }
  };
} else {
  // Tavily не нужен
  return {
    json: {
      needsTavily: false,
      finalResponse: aiResponse,
      chatId: $('Load Static Data'). first().json.chatId
    }
  };
}

