// Получаем Static Data воркфлоу
const staticData = $getWorkflowStaticData('global');

// Инициализируем структуру данных, если её ещё нет
if (!staticData. users) {
  staticData.users = {};
}

// Получаем ID пользователя из Telegram
const chatId = $input.first(). json. message.chat.id;
const userName = $input.first().json. message.from.first_name || "User";

// Инициализируем данные пользователя, если его ещё нет
if (!staticData.users[chatId]) {
  staticData.users[chatId] = {
    learningPlan: [],
    currentConceptIndex: 0,
    completedConcepts: [],
    planConfirmed: false,
    userLevel: "",
    userGoal: "",
    userName: userName
  };
}

// Получаем данные текущего пользователя
const userData = staticData.users[chatId];

// Получаем текст сообщения
