    currentConceptIndex: userData.currentConceptIndex,
    completedConcepts: userData.completedConcepts,
    planConfirmed: userData.planConfirmed,
    userLevel: userData.userLevel,
    userGoal: userData.userGoal
  }
};

const response = $input.first().json. finalResponse;
const chatId = $input.first().json.chatId;

return {
