// Получаем Static Data
const staticData = $getWorkflowStaticData('global');

// Получаем данные из предыдущей ноды
const inputData = $input.first().json;
const chatId = inputData.chatId;
const messageText = inputData.messageText;
const messageTextLower = messageText.toLowerCase();

console.log("=== EXTRACT USER INTENT ===");
console.log("Message:", messageText);
console.log("Chat ID:", chatId);

// Проверяем, существует ли пользователь
if (!staticData.users || ! staticData.users[chatId]) {
  console.log("User not found, returning input data as-is");
  return { json: inputData };
}

const userData = staticData.users[chatId];

console.log("Current user data:");
console.log("- userGoal:", userData.userGoal);
console.log("- userLevel:", userData.userLevel);
console.log("- learningPlan length:", userData.learningPlan. length);
console.log("- planConfirmed:", userData.planConfirmed);

// ========================================
// 1. ИЗВЛЕЧЕНИЕ ЦЕЛИ ОБУЧЕНИЯ (userGoal)
// ========================================
const goalKeywords = ['хочу изучить', 'хочу научиться', 'изучить', 'научиться', 'want to learn', 'learn', 'study'];
const hasGoalKeyword = goalKeywords.some(keyword => messageTextLower.includes(keyword));

if (hasGoalKeyword && ! userData.userGoal) {
  let goal = messageText;

  goal = goal.replace(/хочу изучить|хочу научиться|изучить|научиться|want to learn|learn|study/gi, ''). trim();
  goal = goal.replace(/,?\s*(уровень|level)\s*(начальный|средний|продвинутый|beginner|intermediate|advanced)/gi, '').trim();
  goal = goal.replace(/^[,.\s]+|[,.\s]+$/g, '').trim();

  if (goal.length > 0) {
    userData.userGoal = goal;
    console.log("Extracted userGoal:", goal);
  }
}

// ========================================
// 2. ИЗВЛЕЧЕНИЕ УРОВНЯ (userLevel)
// ========================================
const levelPatterns = [
  { pattern: /начальн|beginner|новичок/i, level: 'начальный' },
  { pattern: /средн|intermediate/i, level: 'средний' },
  { pattern: /продвинут|advanced|expert/i, level: 'продвинутый' }
];

if (! userData.userLevel) {
  for (const {pattern, level} of levelPatterns) {
    if (pattern.test(messageTextLower)) {
      userData.userLevel = level;
      console.log("Extracted userLevel:", level);
      break;
    }
  }
}

// ========================================
// 3. ПРОВЕРКА ПОДТВЕРЖДЕНИЯ ПЛАНА
// ========================================
const confirmKeywords = ['да', 'yes', 'подтверждаю', 'согласен', 'ok', 'ок', '+'];
const isConfirmation = confirmKeywords. some(keyword => {
  const trimmed = messageTextLower.trim();
  return trimmed === keyword || trimmed.includes(keyword);
});

console.log("Is confirmation message:", isConfirmation);
console.log("Learning plan length:", userData.learningPlan.length);
console.log("Plan already confirmed:", userData.planConfirmed);

// ВАЖНО: Подтверждение срабатывает, даже если план пустой
// (план должен быть извлечён в следующей ноде из предыдущего ответа AI)
if (isConfirmation && ! userData.planConfirmed) {
  userData.planConfirmed = true;
  console.log("✅ PLAN CONFIRMED!");
}

// ========================================
// 4. КОМАНДА СБРОСА
// ========================================
const resetKeywords = ['/reset', '/start', 'начать заново', 'новая тема', 'другую тему'];
const shouldReset = resetKeywords.some(keyword => messageTextLower.includes(keyword));

if (shouldReset) {
  userData.learningPlan = [];
  userData.currentConceptIndex = 0;
  userData.completedConcepts = [];
  userData.planConfirmed = false;
  userData.userGoal = "";
  userData.userLevel = "";
  console.log("🔄 User data reset");
}

// Сохраняем обновлённые данные
staticData. users[chatId] = userData;

console.log("=== FINAL USER DATA ===");
console.log(JSON.stringify(userData, null, 2));

// Возвращаем обновлённые данные для AI Agent
return {
  json: {
    chatId: chatId,
    userName: inputData.userName,
    messageText: inputData.messageText,
    learningPlan: userData. learningPlan,
    currentConceptIndex: userData.currentConceptIndex,
    completedConcepts: userData.completedConcepts,
    planConfirmed: userData.planConfirmed,
    userLevel: userData.userLevel,
    userGoal: userData.userGoal
  }
};

// Получаем Static Data
const staticData = $getWorkflowStaticData('global');

if (! staticData.users) {
  staticData.users = {};
}

const inputData = $input. first().json;

let chatId;
try {
  chatId = inputData.chatId || $('Extract Learning Plan').first().json.chatId;
} catch (error) {
  chatId = inputData. chatId;
}

if (! chatId || !staticData.users[chatId]) {
  return {
    json: {
      chatId: chatId,
      message: inputData.output || inputData.finalResponse || ""
    }
  };
}

const userData = staticData.users[chatId];
const aiResponse = inputData.output || inputData.finalResponse || "";

// ========================================
// ОБНОВЛЕНИЕ ПРОГРЕССА ПОСЛЕ ПОСТА
// ========================================

// Проверяем, что это образовательный пост (не вопрос и не подтверждение)
const isPost = userData.planConfirmed && 
               aiResponse.length > 100 && 
               !aiResponse.includes("Подтверждаешь") &&
               ! aiResponse.includes("Чему бы ты хотел") &&
               !aiResponse.includes("Какой у тебя уровень");

if (isPost && userData.currentConceptIndex < userData.learningPlan.length) {
  const currentConcept = userData.learningPlan[userData.currentConceptIndex];

  if (currentConcept && ! userData.completedConcepts. includes(currentConcept)) {
    userData.completedConcepts.push(currentConcept);
    userData.currentConceptIndex++;
    console.log(`Concept completed: ${currentConcept}.  Progress: ${userData.currentConceptIndex}/${userData.learningPlan.length}`);
  }
}

// ========================================
// ПРОВЕРКА ЗАВЕРШЕНИЯ ПЛАНА
// ========================================
if (userData.currentConceptIndex >= userData.learningPlan.length && 
    userData.learningPlan.length > 0 &&
    userData.planConfirmed &&
    aiResponse.includes("Что хочешь изучать дальше")) {

  // Сброс после завершения плана
  userData.learningPlan = [];
  userData.currentConceptIndex = 0;
  userData.completedConcepts = [];
  userData.planConfirmed = false;
  userData.userGoal = "";
  userData.userLevel = "";
  console.log("Learning plan completed and reset");
}

staticData.users[chatId] = userData;

return {
  json: {
    chatId: chatId,
    message: aiResponse
  }
};

// Получаем Static Data
const staticData = $getWorkflowStaticData('global');

// Получаем ответ AI Agent
const aiResponse = $input.first().json. output;

// Получаем Chat ID
let chatId;
try {
  chatId = $('Extract User Intent').first().json. chatId;
} catch (error) {
  console.log("Could not get chatId");
  return { json: { output: aiResponse } };
}

if (! staticData. users || !staticData.users[chatId]) {
  console. log("User not found");
  return { json: { output: aiResponse } };
}

const userData = staticData.users[chatId];

console.log("=== EXTRACT LEARNING PLAN ===");
console.log("Current learningPlan length:", userData.learningPlan. length);

// Извлекаем план ТОЛЬКО если он ещё не сохранён
if (userData.learningPlan.length === 0) {
  console.log("Attempting to extract plan from AI response");

  const plan = [];
  const lines = aiResponse.split('\n');

  let currentTheme = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Ищем заголовок темы (с ## или без)
    const themeMatch = line.match(/^#{0,3}\s*Тема\s+\d+:/i);

    if (themeMatch) {
      currentTheme = line;
      console.log("Found theme:", currentTheme);
      continue;
    }

    // Если мы внутри темы, ищем понятия (строки с дефисом)
    if (currentTheme && line.startsWith('-')) {
      // Убираем дефис и лишние пробелы
      const concept = line.replace(/^-\s*/, '').trim();
      if (concept. length > 0) {
        plan.push(concept);
        console.log("Extracted concept:", concept);
      }
    }

    // Если встретили разделитель (---), останавливаем парсинг
    if (line.startsWith('---')) {
      break;
    }
  }

  if (plan.length > 0) {
    userData.learningPlan = plan;
    staticData.users[chatId] = userData;

    console.log("✅ LEARNING PLAN SAVED");
    console.log("Total concepts:", plan.length);
    console. log("Plan:", JSON.stringify(plan, null, 2));
  } else {
    console. log("❌ No concepts extracted from response");
  }
} else {
  console.log("ℹ️ Learning plan already exists, skipping");
}

return {
  json: {
    output: aiResponse,
    chatId: chatId
  }
};
